package com.gymmind.ai.infrastructure.bailian;
import com.fasterxml.jackson.databind.JsonNode; import com.fasterxml.jackson.databind.ObjectMapper; import com.gymmind.ai.domain.EmbeddingGateway; import org.springframework.http.MediaType; import org.springframework.stereotype.Component; import org.springframework.web.client.RestClient; import java.util.*;
@Component public class BailianEmbeddingAdapter implements EmbeddingGateway { private final RestClient client; private final ObjectMapper mapper=new ObjectMapper(); private final String model; public BailianEmbeddingAdapter(RestClient.Builder builder){String key=System.getenv("DASHSCOPE_API_KEY");this.model=Optional.ofNullable(System.getenv("DASHSCOPE_EMBEDDING_MODEL")).orElse("qwen3.7-text-embedding");this.client=builder.baseUrl(Optional.ofNullable(System.getenv("DASHSCOPE_BASE_URL")).orElse("https://dashscope.aliyuncs.com/compatible-mode/v1")).defaultHeader("Authorization","Bearer "+Optional.ofNullable(key).orElse("")).build();} public List<float[]> embed(List<String> texts){if(texts==null||texts.isEmpty())throw new IllegalArgumentException("texts must not be empty");Map<String,Object> body=Map.of("model",model,"input",Map.of("texts",texts));String raw=client.post().uri("/embeddings").contentType(MediaType.APPLICATION_JSON).body(body).retrieve().body(String.class);try{JsonNode data=mapper.readTree(raw).path("data");List<float[]> out=new ArrayList<>();for(JsonNode row:data){JsonNode emb=row.path("embedding");float[] v=new float[emb.size()];for(int i=0;i<v.length;i++)v[i]=(float)emb.get(i).asDouble();out.add(v);}EmbeddingDimension.validate(out,texts.size());return out;}catch(Exception e){throw new IllegalStateException("invalid embedding response",e);} } }
